{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Testosterone undecanoate, a highly lipophilic long-chain fatty ester prodrug, has an absolute oral bioavailability of only 3.66% in young women, showing that high lipophilicity and a long alkyl ester do not ensure F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester, shows poor and inconsistent oral bioavailability in men, reinforcing the low-F pattern for this lipophilic ester class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Perindopril, an ester prodrug with an amino-acid-derived moiety, has an oral bioavailability of 19% ±7% in healthy subjects, just below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Eliglustat, a lipophilic oral drug, has a simulated absolute oral bioavailability of 8.6%, well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Pravastatin has an absolute oral bioavailability of 17% in humans, below the 20% threshold, despite being an approved oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Hexarelin, a peptide, has an oral bioavailability of only 0.3%, far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "A dodecyl ester dipeptide (DVAS) showed average oral bioavailability of 60% in healthy volunteers, providing a counterexample of a long-chain lipophilic ester with high F; however, its transfer score is low.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "Oseltamivir, an ethyl ester prodrug, has an absolute oral bioavailability of 79% in healthy volunteers, but its lower transferability and different physicochemical profile limit direct relevance to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valomaciclovir stearate, a long-chain fatty ester prodrug, achieved >60% oral bioavailability in humans, but the very low transfer score makes it a weak counterexample.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a highly lipophilic N-formyl-L-leucine ester of a beta-lactone with a long alkyl chain. The strongest transferable evidence comes from long-chain lipophilic ester prodrugs (testosterone undecanoate, dimethandrolone undecanoate) with absolute oral bioavailability of ~3.7–6.8% or poor/inconsistent absorption, well below 20%. Additional moderate-transfer drugs (perindopril, eliglustat, pravastatin) also fall below 20%. The high-F counterexamples (DVAS, oseltamivir, valomaciclovir stearate) have much lower transfer scores and are mechanistically distinct. Therefore, F ≥20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself; prediction relies on analogue evidence.",
    "The high-F analogues have low transfer scores, so their relevance to the query is uncertain.",
    "The physicochemical prior is mixed/unclear and does not provide a definitive direction.",
    "Potential GI hydrolysis of the beta-lactone/ester and systemic exposure of metabolites is not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

